// Mirrors the backend DTOs (records) field for field. The backend rejects unknown JSON fields, so request
// types must never carry extra properties. Generated by hand from the Java records; once the build runs,
// replace with types generated from /v3/api-docs (see NOTES.md).

export type UUID = string;
/** ISO-8601 instant, e.g. 2026-10-13T10:00:00Z */
export type Instant = string;
/** ISO-8601 date, e.g. 2026-10-13 */
export type LocalDate = string;

export interface Money {
  amountMinor: number;
  currency: string;
  formatted: string;
}

export interface Page<T> {
  items: T[];
  page: number;
  size: number;
  totalItems: number;
  totalPages: number;
  hasNext: boolean;
}

// ---------- identity ----------
export type Role = 'CUSTOMER' | 'CUSTOMER_SERVICE' | 'INVENTORY_MANAGER' | 'PURCHASING_MANAGER' | 'FINANCE_MANAGER' | 'ADMIN';
export const ROLES: Role[] = ['CUSTOMER', 'CUSTOMER_SERVICE', 'INVENTORY_MANAGER', 'PURCHASING_MANAGER', 'FINANCE_MANAGER', 'ADMIN'];
export type ActorType = 'USER' | 'API_KEY' | 'ANONYMOUS' | 'SYSTEM';

export interface RegisterRequest { email: string; password: string; fullName: string; }
export interface LoginRequest { email: string; password: string; }
export interface RefreshRequest { refreshToken: string; }
export interface ChangePasswordRequest { currentPassword: string; newPassword: string; }
export interface TokenResponse { accessToken: string; tokenType: string; expiresIn: number; refreshToken: string; refreshExpiresIn: number; }
export interface WhoAmI { userId: UUID; actorType: ActorType; apiKeyId: UUID | null; scopes: string[]; }
export interface UserProfile { id: UUID; email: string; fullName: string; role: Role; createdAt: Instant; }

/** Spending guardrails for THIS key only (backend REVIEW.md §5.3); a human session is never limited by these. */
export interface AgentLimits {
  maxOrderValueMinor: number | null;
  maxOrdersPerDay: number | null;
  requireApprovalAboveMinor: number | null;
}
export interface ApiKey {
  id: UUID; name: string; prefix: string; scopes: string[]; expiresAt: Instant;
  lastUsedAt: Instant | null; revokedAt: Instant | null; createdAt: Instant; active: boolean; limits: AgentLimits;
}
export interface CreateApiKeyRequest {
  name: string; scopes: string[]; expiresInDays?: number;
  maxOrderValueMinor?: number | null; maxOrdersPerDay?: number | null; requireApprovalAboveMinor?: number | null;
}
export interface CreatedApiKey { key: ApiKey; apiKey: string | null; warning: string; }

export interface AdminUser { id: UUID; email: string; fullName: string; role: Role; scopes: string[]; enabled: boolean; createdAt: Instant; updatedAt: Instant; }
export interface RoleInfo { role: Role; scopes: string[]; }

// ---------- catalog ----------
export type ProductSort = 'NEWEST' | 'NAME_ASC' | 'PRICE_ASC' | 'PRICE_DESC';
export interface Category { id: UUID; name: string; slug: string; description: string | null; }
export interface CategoryRequest { name: string; description?: string | null; }
export interface Product {
  id: UUID; sku: string; name: string; description: string | null; imageUrl: string | null; price: Money; availableQuantity: number;
  inStock: boolean; categoryId: UUID | null; active: boolean; createdAt: Instant; updatedAt: Instant;
}
export interface CreateProductRequest {
  sku: string; name: string; description?: string | null; imageUrl?: string | null; priceMinor: number; initialStock?: number;
  unitCostMinor?: number; categoryId?: UUID | null; active?: boolean;
}
export interface UpdateProductRequest {
  sku: string; name: string; description?: string | null; imageUrl?: string | null; priceMinor: number; categoryId?: UUID | null;
  active?: boolean;
}

// ---------- cart & orders ----------
export interface CartLine {
  productId: UUID; sku: string | null; name: string | null; unitPrice: Money | null; quantity: number;
  lineTotal: Money | null; availableQuantity: number | null; issue: string | null;
}
export interface Cart { items: CartLine[]; totalQuantity: number; subtotal: Money; readyForCheckout: boolean; updatedAt: Instant | null; }
export interface CartQuote { countryCode: string; subtotal: Money; taxRateBasisPoints: number; tax: Money; total: Money; readyForCheckout: boolean; }
export interface AddCartItemRequest { productId: UUID; quantity: number; }
export interface UpdateCartItemRequest { quantity: number; }

export type OrderStatus = 'PENDING_PAYMENT' | 'PAID' | 'SHIPPED' | 'DELIVERED' | 'CANCELLED';
export const ORDER_STATUSES: OrderStatus[] = ['PENDING_PAYMENT', 'PAID', 'SHIPPED', 'DELIVERED', 'CANCELLED'];
export type CancelReason = 'CUSTOMER' | 'STAFF' | 'EXPIRED';
export interface ShippingAddress {
  recipientName: string; line1: string; line2: string | null; city: string; region: string | null;
  postalCode: string; countryCode: string;
}
export interface OrderLine { productId: UUID; sku: string; productName: string; unitPrice: Money; quantity: number; lineTotal: Money; }
export interface Order {
  id: UUID; orderNumber: string; status: OrderStatus; cancelReason: CancelReason | null; items: OrderLine[];
  subtotal: Money; taxRateBasisPoints: number; tax: Money; total: Money; refunded: Money;
  shippingAddress: ShippingAddress; allowedActions: string[]; allowedNextStatuses: OrderStatus[];
  expiresAt: Instant | null; paidAt: Instant | null; shippedAt: Instant | null; deliveredAt: Instant | null;
  createdAt: Instant; updatedAt: Instant;
  placedByApiKeyId: UUID | null; approvalState: ApprovalState | null; approvalDecidedAt: Instant | null;
}
export interface CheckoutRequest { shippingAddress: ShippingAddress; expectedTotalMinor: number; }
export interface UpdateOrderStatusRequest { status: OrderStatus; }
/** Null unless an agent placed the order; PENDING blocks payment until the owner approves or rejects it. */
export type ApprovalState = 'PENDING' | 'APPROVED' | 'REJECTED' | 'EXPIRED';

export interface Invoice {
  id: UUID; invoiceNumber: string; orderId: UUID; orderNumber: string; issuedAt: Instant; billTo: ShippingAddress;
  lines: OrderLine[]; subtotal: Money; taxRateBasisPoints: number; tax: Money; total: Money; refunded: Money;
}

// ---------- returns ----------
export type ReturnStatus = 'REQUESTED' | 'APPROVED' | 'REJECTED' | 'RECEIVED' | 'REFUNDED';
export const RETURN_STATUSES: ReturnStatus[] = ['REQUESTED', 'APPROVED', 'REJECTED', 'RECEIVED', 'REFUNDED'];
export interface ReturnLine { productId: UUID; sku: string; productName: string; quantity: number; unitPrice: Money; lineTotal: Money; }
export interface ReturnRequest {
  id: UUID; rmaNumber: string; orderId: UUID; status: ReturnStatus; reason: string; resolutionNote: string | null;
  lines: ReturnLine[]; merchandiseTotal: Money; refundId: UUID | null; allowedNextStatuses: ReturnStatus[];
  createdAt: Instant; updatedAt: Instant;
}
export interface CreateReturnRequest { reason: string; lines: { productId: UUID; quantity: number }[]; }
export interface ReturnDecisionRequest { note?: string | null; }
export interface SodOverrideRequest { sodOverrideReason?: string | null; }

// ---------- inventory ----------
export type MovementType = 'OPENING' | 'ADJUSTMENT' | 'SALE' | 'SALE_CANCELLED' | 'PURCHASE_RECEIPT' | 'CUSTOMER_RETURN';
export const MOVEMENT_TYPES: MovementType[] = ['OPENING', 'ADJUSTMENT', 'SALE', 'SALE_CANCELLED', 'PURCHASE_RECEIPT', 'CUSTOMER_RETURN'];
export interface InventoryItem {
  productId: UUID; sku: string; name: string; active: boolean; onHand: number; reserved: number; available: number;
  unitCost: Money; stockValue: Money; reorderPoint: number; reorderQuantity: number; preferredSupplierId: UUID | null;
}
export interface StockMovement {
  id: UUID; productId: UUID; sku: string; productName: string; type: MovementType; quantity: number; unitCost: Money; value: Money | null;
  stockAfter: number; referenceType: string | null; referenceId: UUID | null; note: string | null;
  actorId: UUID | null; createdAt: Instant;
}
export interface InventoryValuation { items: Page<InventoryItem>; totalUnits: number; totalValue: Money; asOf: Instant; }
export interface StockAdjustmentRequest { delta: number; reason: string; }
export interface ReorderPolicyRequest { reorderPoint: number; reorderQuantity: number; preferredSupplierId?: UUID | null; }
export interface ReorderSuggestion {
  productId: UUID; sku: string; name: string; onHand: number; reserved: number; available: number; onOrder: number;
  reorderPoint: number; suggestedQuantity: number; preferredSupplierId: UUID | null; preferredSupplierName: string | null;
  estimatedUnitCost: Money;
}

// ---------- purchasing ----------
export interface Supplier {
  id: UUID; code: string; name: string; email: string | null; phone: string | null; address: string | null;
  paymentTermsDays: number; active: boolean; createdAt: Instant;
}
export interface SupplierRequest {
  code: string; name: string; email?: string | null; phone?: string | null; address?: string | null;
  paymentTermsDays: number; active?: boolean;
}
export type PurchaseOrderStatus = 'DRAFT' | 'SUBMITTED' | 'APPROVED' | 'PARTIALLY_RECEIVED' | 'RECEIVED' | 'CANCELLED';
export const PURCHASE_ORDER_STATUSES: PurchaseOrderStatus[] = ['DRAFT', 'SUBMITTED', 'APPROVED', 'PARTIALLY_RECEIVED', 'RECEIVED', 'CANCELLED'];
export interface PurchaseOrderLine {
  lineNo: number; productId: UUID; sku: string; productName: string; quantityOrdered: number; quantityReceived: number;
  quantityOutstanding: number; unitCost: Money; lineTotal: Money;
}
export interface PurchaseOrder {
  id: UUID; poNumber: string; supplierId: UUID; supplierName: string; status: PurchaseOrderStatus; lines: PurchaseOrderLine[]; total: Money;
  expectedDate: LocalDate | null; notes: string | null; createdBy: UUID; approvedBy: UUID | null; approvedAt: Instant | null;
  allowedActions: string[]; createdAt: Instant; updatedAt: Instant;
}
export interface PurchaseOrderLineRequest { productId: UUID; quantity: number; unitCostMinor: number; }
export interface PurchaseOrderRequest { supplierId: UUID; expectedDate?: LocalDate | null; notes?: string | null; lines: PurchaseOrderLineRequest[]; }
export interface GoodsReceiptRequest { lines: { productId: UUID; quantity: number }[]; note?: string | null; sodOverrideReason?: string | null; }
export interface GoodsReceiptLine { productId: UUID; sku: string; productName: string; quantity: number; unitCost: Money; }
export interface GoodsReceipt {
  id: UUID; receiptNumber: string; purchaseOrderId: UUID; lines: GoodsReceiptLine[];
  totalCost: Money; note: string | null; receivedBy: UUID; receivedAt: Instant;
}
export interface DraftsFromSuggestions { created: PurchaseOrder[]; skippedProductIdsWithoutSupplier: UUID[]; skippedInactiveSupplierIds: UUID[]; }

// ---------- finance ----------
export type PaymentMethod = 'CARD' | 'BANK_TRANSFER' | 'CASH' | 'OTHER';
export const PAYMENT_METHODS: PaymentMethod[] = ['CARD', 'BANK_TRANSFER', 'CASH', 'OTHER'];
export type PaymentOutcome = 'APPLIED' | 'APPLIED_AFTER_REINSTATEMENT' | 'REFUNDED_ORDER_EXPIRED' | 'REFUNDED_ORDER_CANCELLED';
export interface RecordPaymentRequest { method: PaymentMethod; amountMinor: number; reference?: string | null; }
/** BE-1: an order as finance sees it (no address or items). customerEmail/Name are null only if the account is gone. */
export interface FinanceOrder {
  id: UUID; orderNumber: string; status: OrderStatus; cancelReason: CancelReason | null; customerId: UUID;
  customerEmail: string | null; customerName: string | null; total: Money; expiresAt: Instant | null;
  paidAt: Instant | null; createdAt: Instant;
}
export interface Payment {
  id: UUID; orderId: UUID; amount: Money; method: PaymentMethod; reference: string | null; outcome: PaymentOutcome;
  recordedBy: UUID; createdAt: Instant; invoiceId: UUID | null; invoiceNumber: string | null; refundId: UUID | null;
  creditNoteNumber: string | null;
}
export interface Refund {
  id: UUID; creditNoteNumber: string; orderId: UUID; returnId: UUID | null; amount: Money; tax: Money; reason: string;
  createdBy: UUID | null; createdAt: Instant;
}
export interface TaxRate { countryCode: string; name: string; rateBasisPoints: number; ratePercent: string; active: boolean; }
export interface TaxRateRequest { name: string; rateBasisPoints: number; active: boolean; }
export type AccountType = 'ASSET' | 'LIABILITY' | 'EQUITY' | 'REVENUE' | 'EXPENSE';
export interface LedgerAccount { code: string; name: string; type: AccountType; }
export interface JournalLine { accountCode: string; debitMinor: number; creditMinor: number; }
export interface JournalEntry {
  id: UUID; entryNumber: string; postedAt: Instant; description: string; sourceType: string; sourceId: UUID | null;
  createdBy: UUID | null; lines: JournalLine[];
}
export interface TrialBalanceLine { accountCode: string; accountName: string; type: AccountType; debitMinor: number; creditMinor: number; balanceMinor: number; }
export interface TrialBalance { accounts: TrialBalanceLine[]; totalDebitMinor: number; totalCreditMinor: number; balanced: boolean; }
export interface SalesSummary {
  from: LocalDate; to: LocalDate; invoicesIssued: number; grossSales: Money; taxInvoiced: Money; refundsIssued: number;
  refundedTotal: Money; refundedTax: Money; netSales: Money;
}

// ---------- audit ----------
export const AUDIT_ACTIONS = [
  'ADMIN_BOOTSTRAPPED', 'USER_REGISTERED', 'LOGIN_SUCCEEDED', 'LOGIN_FAILED', 'LOGIN_BLOCKED_LOCKED', 'ACCOUNT_LOCKED',
  'REFRESH_TOKEN_REUSED', 'PASSWORD_CHANGED', 'API_KEY_CREATED', 'API_KEY_REVOKED', 'USER_ROLE_CHANGED', 'USER_DISABLED',
  'USER_ENABLED', 'LOGIN_THROTTLED', 'LOGIN_ACCOUNT_CEILING_REACHED', 'CREDENTIALS_REVOKED', 'ACCESS_DENIED',
  'API_KEY_REJECTED', 'RATE_LIMITED', 'SOD_OVERRIDDEN', 'CATEGORY_CREATED', 'CATEGORY_UPDATED', 'CATEGORY_DELETED',
  'PRODUCT_CREATED', 'PRODUCT_UPDATED', 'PRODUCT_DEACTIVATED', 'STOCK_ADJUSTED', 'REORDER_POLICY_CHANGED',
  'SUPPLIER_CREATED', 'SUPPLIER_UPDATED', 'SUPPLIER_DEACTIVATED', 'PURCHASE_ORDER_CREATED', 'PURCHASE_ORDER_UPDATED',
  'PURCHASE_ORDER_SUBMITTED', 'PURCHASE_ORDER_APPROVED', 'PURCHASE_ORDER_CANCELLED', 'GOODS_RECEIVED', 'ORDER_PLACED',
  'ORDER_AWAITING_APPROVAL', 'AGENT_ORDER_APPROVED', 'AGENT_ORDER_REJECTED', 'AGENT_LIMIT_BLOCKED',
  'ORDER_CANCELLED', 'ORDER_STATUS_CHANGED', 'ORDER_EXPIRED', 'ORDER_REINSTATED_AFTER_LATE_PAYMENT',
  'ORDER_EXPIRED_PAYMENT_REFUNDED', 'ORDER_CANCELLED_PAYMENT_REFUNDED', 'RETURN_REQUESTED', 'RETURN_APPROVED',
  'RETURN_REJECTED', 'RETURN_RECEIVED', 'RETURN_REFUNDED', 'TAX_RATE_CHANGED', 'PAYMENT_RECORDED', 'INVOICE_ISSUED',
  'REFUND_ISSUED',
] as const;
export type AuditAction = (typeof AUDIT_ACTIONS)[number];
export const ACTOR_TYPES: ActorType[] = ['USER', 'API_KEY', 'ANONYMOUS', 'SYSTEM'];
export interface AuditEvent {
  id: UUID; occurredAt: Instant; actorId: UUID | null; actorType: ActorType; apiKeyId: UUID | null; action: AuditAction;
  targetType: string | null; targetId: string | null; ipAddress: string | null; requestId: string | null; details: string | null;
}
